 if(kind==='person')fields=`<label>تصنيف الفرد<select name="person_type"><option value="staff">كادر الشركة</option><option value="contractor">مقاول باطن</option></select></label><label>المنطقة<select name="region">${Object.keys(cache).map(k=>`<option value="${k}">${regions[k]}</option>`).join('')}</select></label><label>الاسم الكامل<input name="full_name" required maxlength="160" value="${E(x.full_name)}"></label><label>الرقم الوظيفي<input name="employee_code" maxlength="80" value="${E(x.employee_code)}"></label><label>جهة العمل / اسم المقاول<input name="employer" required maxlength="160" value="${E(x.employer)}"></label><label>المسمى الوظيفي<input name="job_title" required maxlength="160" value="${E(x.job_title)}"></label><label>الفريق<select name="team_id"><option value="">غير مسند لفريق</option>${teams.map(t=>`<option value="${t.id}">${E(t.name)}</option>`).join('')}</select></label><label>المسؤول المباشر<input name="direct_manager" maxlength="160" value="${E(x.direct_manager)}"></label><label>جوال العمل<input name="phone" maxlength="40" value="${E(x.phone)}"></label><label>الإدارة / القسم<input name="department" maxlength="160" value="${E(x.department)}"></label><label>التخصص<input name="specialty" maxlength="160" value="${E(x.specialty)}"></label><label>نوع التعاقد<select name="employment_type"><option value="other">أخرى / غير محدد</option><option value="permanent">دائم</option><option value="fixed_term">محدد المدة</option><option value="daily">يومي</option><option value="outsourced">تعهيد</option></select></label><label>تاريخ المباشرة<input name="start_date" type="date" value="${E(x.start_date)}"></label><label>تاريخ انتهاء العقد<input name="contract_end_date" type="date" value="${E(x.contract_end_date)}"></label><label>سبب التحديث / التعيين<input name="change_reason" maxlength="1000" placeholder="مطلوب للحركة الوظيفية"></label>`;
 if(kind==='team')fields=`<label>المنطقة<select name="region">${Object.keys(cache).map(k=>`<option value="${k}">${regions[k]}</option>`).join('')}</select></label><label>اسم الفريق<input name="name" required maxlength="160" value="${E(x.name)}"></label><label>الفئة<select name="category">${categories()}</select></label><label>المشرف<input name="supervisor" maxlength="160" value="${E(x.supervisor)}"></label><label>العدد المخطط<input name="planned_headcount" type="number" min="0" step="1" value="${E(x.planned_headcount)}"></label>`;
 if(kind==='coverage')fields=`<label>المنطقة<select name="region">${Object.keys(cache).map(k=>`<option value="${k}">${regions[k]}</option>`).join('')}</select></label><label>الفريق<select name="team_id" required>${teams.map(t=>`<option value="${t.id}">${E(t.name)}</option>`).join('')}</select></label><label>الرقم الوزاري / رمز المبنى<input name="building_code" required maxlength="100" value="${E(x.building_code)}"></label><label>اسم المبنى<input name="building_name" required maxlength="200" value="${E(x.building_name)}"></label><label>مكتب التعليم<input name="education_office" maxlength="160" value="${E(x.education_office)}"></label><label>نوع الخدمة<select name="service">${categories()}</select></label>`;
 const body=d.querySelector('[data-body]'),v337Unavailable=Object.values(cache).some(z=>z.advancedUnavailable);body.innerHTML=`<form class="fm334-form">${fields}${kind==='person'&&v337Unavailable?'<p class="fm337-warning wide">حقول القسم والتخصص والتعاقد والتواريخ تتطلب ترحيل V337، وقد تم إيقافها مؤقتًا.</p>':''}<label class="check"><input name="active" type="checkbox" ${x.active===false?'':'checked'}> نشط</label><label class="wide">ملاحظة / مصدر البيانات<textarea name="note" maxlength="2000">${E(x.note)}</textarea></label><p class="wide" data-error role="alert"></p><footer class="wide"><button class="primary" type="submit">حفظ</button><button type="button" data-cancel>إلغاء</button></footer></form>`;
